import json
from google import genai

client = genai.Client()

# 1. Declarar la herramienta (esquema de la funciÃ³n).
weather_tool = {
    "type": "function",
    "name": "get_current_temperature",
    "description": "Gets the current temperature for a given location.",
    "parameters": {
        "type": "object",
        "properties": {
            "location": {"type": "string", "description": "The city name, e.g. San Francisco"},
        },
        "required": ["location"],
    },
}

# 2. Funciones locales (el modelo NO las ejecuta; las ejecutas tÃº).
available_functions = {
    "get_current_temperature": lambda location: {
        "location": location, "temperature": "22", "unit": "celsius"
    },
}

user_input = "What is the temperature in London?"
previous_id = None

# 3. Bucle: el modelo pide la funciÃ³n â la ejecutas â devuelves el resultado.
while True:
    interaction = client.interactions.create(
        model="gemini-3.6-flash",
        input=user_input,
        tools=[weather_tool],
        previous_interaction_id=previous_id,
    )

    function_results = []
    for step in interaction.steps:
        if step.type == "function_call":
            result = available_functions[step.name](**step.arguments)
            print(f"Called {step.name}({step.arguments}) â {result}")
            function_results.append({
                "type": "function_result",
                "name": step.name,
                "call_id": step.id,
                "result": [{"type": "text", "text": json.dumps(result)}],
            })

    if not function_results:
        break  # ya no hay mÃ¡s funciones que llamar

    user_input = function_results
    previous_id = interaction.id

print(interaction.output_text)

(function () {
  const nodes = [
    { id: "user",   label: "Usuario",  sub: "input", x: 70,  y: 230 },
    { id: "client", label: "Client",   sub: "genai.Client", x: 210, y: 100 },
    { id: "api",    label: "API",      sub: "interactions.create", x: 390, y: 100 },
    { id: "model",  label: "Modelo",   sub: "gemini-3.6-flash", x: 570, y: 100 },
    { id: "func",   label: "FunciÃ³n",  sub: "function_call", x: 570, y: 360 },
    { id: "resp",   label: "Respuesta", sub: "output_text", x: 810, y: 230 },
  ];
  const edges = [
    { from: "user",   to: "client", label: "input", loop: false },
    { from: "client", to: "api",    label: "create", loop: false },
    { from: "api",    to: "model",  label: "prompt", loop: false },
    { from: "model",  to: "func",   label: "function_call", loop: true },
    { from: "func",   to: "model",  label: "function_result", loop: true },
    { from: "model",  to: "resp",   label: "output", loop: false },
    { from: "resp",   to: "user",   label: "devuelve", loop: false },
  ];
  const pos = Object.fromEntries(nodes.map(n => [n.id, { x: n.x, y: n.y }]));
  const svg = document.getElementById("grafo");
  const NS = "http://www.w3.org/2000/svg";
  function el(tag, attrs) { const e = document.createElementNS(NS, tag); for (const k in attrs) e.setAttribute(k, attrs[k]); return e; }

  const edgePaths = [], edgeArrows = [], edgeGeom = [];
  edges.forEach((ed) => {
    const a = pos[ed.from], b = pos[ed.to];
    let d, mid;
    if (ed.loop) {
      const dir = ed.from === "model" ? 1 : -1;
      const cx = 570 + dir * 150, cy = (a.y + b.y) / 2;
      d = `M ${a.x} ${a.y} C ${cx} ${a.y}, ${cx} ${b.y}, ${b.x} ${b.y}`;
      mid = { x: cx, y: cy };
    } else if (ed.from === "resp") {
      d = `M ${a.x} ${a.y} C ${(a.x+b.x)/2} 460, ${(a.x+b.x)/2} 460, ${b.x} ${b.y}`;
      mid = { x: (a.x + b.x) / 2, y: 430 };
    } else {
      const dx = Math.abs(b.x - a.x), dy = Math.abs(b.y - a.y);
      if (dy > dx) {
        const my = (a.y + b.y) / 2;
        d = `M ${a.x} ${a.y} C ${a.x} ${my}, ${b.x} ${my}, ${b.x} ${b.y}`;
        mid = { x: (a.x + b.x) / 2, y: my };
      } else {
        const mx = (a.x + b.x) / 2;
        d = `M ${a.x} ${a.y} C ${mx} ${a.y}, ${mx} ${b.y}, ${b.x} ${b.y}`;
        mid = { x: mx, y: (a.y + b.y) / 2 };
      }
    }
    const path = el("path", { class: "edge", d });
    svg.appendChild(path); edgePaths.push(path);
    const ang = Math.atan2(b.y - mid.y, b.x - mid.x);
    const tx = b.x - 18 * Math.cos(ang), ty = b.y - 18 * Math.sin(ang);
    const arrow = el("path", { class: "arrow", d: `M ${tx} ${ty} l 8 ${-4} l -8 ${-4} z`, transform: `rotate(${ang*180/Math.PI} ${tx} ${ty})` });
    svg.appendChild(arrow); edgeArrows.push(arrow);
    edgeGeom.push({ a, b });
  });

  const nodeGroups = {};
  nodes.forEach(n => {
    const g = el("g", { class: "node" });
    const w = n.id === "api" ? 150 : 130;
    g.appendChild(el("rect", { x: n.x - w/2, y: n.y - 29, width: w, height: 58 }));
    const t = el("text", { class: "t", x: n.x, y: n.y - 4, "text-anchor": "middle" }); t.textContent = n.label;
    const s = el("text", { class: "s", x: n.x, y: n.y + 16, "text-anchor": "middle" }); s.textContent = n.sub;
    g.appendChild(t); g.appendChild(s); svg.appendChild(g); nodeGroups[n.id] = g;
  });

  const travel = el("circle", { class: "travel", r: 6, opacity: 0 });
  svg.appendChild(travel);
  const caption = document.getElementById("caption");
  const N = edges.length;
  let i = 0, raf = null;

  function clearActive() {
    nodes.forEach(n => nodeGroups[n.id].classList.remove("active"));
    edgePaths.forEach(p => p.classList.remove("active"));
    edgeArrows.forEach(a => a.classList.remove("active"));
  }
  function animateEdge(idx) {
    const ed = edges[idx];
    clearActive();
    edgePaths[idx].classList.add("active");
    edgeArrows[idx].classList.add("active");
    nodeGroups[ed.from].classList.add("active");
    caption.innerHTML = `Paso ${idx+1}/${N}: <b>${ed.from}</b> â <b>${ed.to}</b> (${ed.label})`;
    const path = edgePaths[idx], len = path.getTotalLength();
    const t0 = performance.now(), dur = 900;
    function step(now) {
      let p = (now - t0) / dur; if (p > 1) p = 1;
      const pt = path.getPointAtLength(p * len);
      travel.setAttribute("cx", pt.x); travel.setAttribute("cy", pt.y);
      travel.setAttribute("opacity", 1);
      if (p < 1) raf = requestAnimationFrame(step);
      else { nodeGroups[ed.to].classList.add("active"); i = (i + 1) % N; setTimeout(() => animateEdge(i), 320); }
    }
    raf = requestAnimationFrame(step);
  }
  function start() { cancelAnimationFrame(raf); i = 0; animateEdge(0); }
  svg.addEventListener("click", start);
  start();
})();

function descargarMD() {
  const md = document.getElementById('md-resumen').textContent.trim();
  const blob = new Blob([md], { type: 'text/markdown;charset=utf-8' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = 'resumen-gemini.md';
  document.body.appendChild(a);
  a.click();
  a.remove();
  URL.revokeObjectURL(url);
}
